INSERT INTO `mst_shops` (`id`, `id_shop_group`, `name`, `email`, `notify_email`, `daily_report_status`, `short_code`, `phone`, `image`, `address`, `city`, `id_state`, `id_country`, `postcode`, `note`, `cancellation_policy`, `other_policy`, `feedback_url`, `social_links`, `rateletter_url`, `email_format_url`, `website_url`, `status`, `id_mst_user_created_by`, `base_currency_code`, `date_created`, `last_modified`, `id_mst_user_modified_by`) VALUES
(1, 1, 'Roomstatushub', 'support@roomstatushub.com', '', 0, 'RSH', '9654255581', 'logo90055.png', 'Chattarpur', 'New Delhi', 346, 105, '110028', 'As per the government of India norms, you are requested to carry a valid photo id with complete address and produce it at the time of check in. For Indian nationals: driver''s license, passport, voter id or Aadhar card only. Pan card will not be considered as a valid address proof & for international travelers: passport.', '<ul>\r\n	<li>Full retention will be charged for cancellation received 10 days prior to arrival.</li>\r\n	<li>In the unlikely event of our inability to provide the above accommodation, we will arrange alternate accommodation of similar standards and provide transport to the guest at our cost.</li>\r\n	<li>No cancellation charges if cancelled more than 15 days prior to arrival.</li>\r\n	<li>One day pro-rata cancellation charges will be forfeited/levied for cancellation received 11-14 days prior to arrival.</li>\r\n	<li>The above cancellation policy is not valid during long weekends, Christmas, New Year and during certain other times of the year wherein rooms will be confirmed subject to non refundable advance.</li>\r\n</ul>\r\n', '<p>Enjoy the perks of being a holder of WelcomHeritage Privilege Card.</p>\r\n\r\n<p><img alt="" src="http://crs.roomstatushub.com/uploaded_files/uploads/4fa7ee8.jpg" /><br />\r\n<strong>DISCOVER PRIVILEGE CARD BENEFITS</strong></p>\r\n\r\n<ul>\r\n	<li>20% discount on the Heritage Holiday Packages.</li>\r\n	<li>20% discount on food and soft beverages.</li>\r\n	<li>Exclusive monthly Promotional offers.</li>\r\n</ul>\r\n\r\n<p>Thanking you for patronising WelcomHeritage properties and assuring you of our best services and attention at all&nbsp;times.</p>\r\n', 'http://www.welcomheritagehotels.in/feedback.html', '', 'roomstatushubexcel.php', '', '', 1, 0, 0, '2018-11-30 00:00:00', '2018-03-16 19:38:20', 9),
(2, 1, 'WELCOMHERITAGE', 'holidays@welcomheritagehotels.in', 'support@roomstatushub.com', 1, 'WH', '', 'company-logo294.jpg', '', 'New Delhi', 346, 105, '', 'As per the government of India norms, you are requested to carry a valid photo id with complete address and produce it at the time of check in. For Indian nationals: driver''s license, passport, voter id or Aadhar card only. Pan card will not be considered as a valid address proof & for international travelers: passport.', '<ul>\r\n	<li>Full retention will be charged for cancellation received 10 days prior to arrival.</li>\r\n	<li>In the unlikely event of our inability to provide the above accommodation, we will arrange alternate accommodation of similar standards and provide transport to the guest at our cost.</li>\r\n	<li>No cancellation charges if cancelled more than 15 days prior to arrival.</li>\r\n	<li>One day pro-rata cancellation charges will be forfeited/levied for cancellation received 11-14 days prior to arrival.</li>\r\n	<li>The above cancellation policy is not valid during long weekends, Christmas, New Year and during certain other times of the year wherein rooms will be confirmed subject to non refundable advance.</li>\r\n</ul>\r\n\r\n<p style="margin:0cm 0cm 8pt"><span style="font-size:11pt"><span style="line-height:107%"><span style="font-family:Calibri,sans-serif"><b>Guest grants the consent for processing the Guest data for enhancement of the service experience.</b></span></span></span></p>\r\n', '<p>Enjoy the perks of being a holder of WelcomHeritage Privilege Card.</p>\r\n\r\n<p><img alt="" src="http://crs.roomstatushub.com/uploaded_files/uploads/4fa7ee8.jpg" /><br />\r\n<strong>DISCOVER PRIVILEGE CARD BENEFITS</strong></p>\r\n\r\n<ul>\r\n	<li>20% discount on the Heritage Holiday Packages.</li>\r\n	<li>20% discount on food and soft beverages.</li>\r\n	<li>Exclusive monthly Promotional offers.</li>\r\n</ul>\r\n\r\n<p>Thanking you for patronising WelcomHeritage properties and assuring you of our best services and attention at all&nbsp;times.</p>\r\n', 'http://www.welcomheritagehotels.in/feedback.html', '', '', '', 'https://welcomheritagehotels.in', 1, 0, 0, '2018-01-29 11:35:43', '2018-06-21 18:03:55', 9),
(3, 1, 'Test', 'test@test.com', '', 0, '', '', '190084.png', '', 'test', 342, 105, '', '', '', '', '', '', '', '', '', 1, 0, 0, '2018-01-29 12:41:03', '2018-01-29 14:56:59', 9),
(4, 1, 'Consortium Hotels', 'reservations@consortiumhotels.in', 'support@roomstatushub.com', 1, 'TCH', '45665201', 'logo70547.png', 'Consortium Resorts & Inns Pvt Ltd.\r\n\r\nD-1/31, First Floor , Palam Extension , Sector -7 , Dwarka ', 'Delhi', 346, 105, '110075', 'As per the government of India norms, you are requested to carry a valid photo id with complete address and produce it at the time of check in. For Indian nationals: driver''s license, passport, voter id or Aadhar card only. Pan card will not be considered as a valid address proof.For Foreign Nationals : passport.', '<p style="margin-right:-5.65pt; text-align:justify; margin:0cm 0cm 8pt"><span style="font-size:11pt"><span style="line-height:normal"><span style="font-family:Calibri,sans-serif"><b>We are holding your booking as per the information above , for CONFIRMATIONS , Please follow the below Instructions :</b></span></span></span></p>\r\n\r\n<p style="margin-right:-5.65pt; text-align:justify; margin:0cm 0cm 8pt"><span style="font-size:11pt"><span style="line-height:normal"><span style="font-family:Calibri,sans-serif">&nbsp;<b><u>Allocation/Confirmation Policy</u></b></span></span></span></p>\r\n\r\n<ul>\r\n	<li style="margin-right:-5.65pt; text-align:justify; margin:0cm 0cm 8pt"><span style="font-size:11pt"><span style="line-height:normal"><span style="tab-stops:list 36.0pt"><span style="font-family:Calibri,sans-serif">Based on the availability status, the rooms will be allocated on FIRST COME FIRST SERVE BASIS for the bookings received.&nbsp;Confirmation will be provided only after receipt of pre-payment / service voucher, Naming List and other requested details.</span></span></span></span></li>\r\n	<li style="margin-right:-5.65pt; text-align:justify; margin:0cm 0cm 8pt"><span style="font-size:11pt"><span style="line-height:normal"><span style="tab-stops:list 36.0pt"><span style="font-family:Calibri,sans-serif"><span style="color:black">The Tour operator shall submit the operations Status 45 days prior to the arrival .Final Rooming list along with vouchers to reach us 30 days prior to arrival .Should the Tour operator fail to supply such information as specified, the hotel reserve the right to release the reserved accommodations.</span></span></span></span></span></li>\r\n	<li style="margin-right:-5.65pt; text-align:justify; margin:0cm 0cm 8pt"><span style="font-size:11pt"><span style="line-height:normal"><span style="tab-stops:list 36.0pt"><span style="font-family:Calibri,sans-serif"><span style="color:black">Your booking is CONFIRMED &nbsp;against <b>your Voucher /Advance Payments</b> . Any amendment henceforth will not be acceptable ( after 30 days prior to check in ) and will be subjected to Cancelation policy as per the Contract letter.</span></span></span></span></span></li>\r\n</ul>\r\n\r\n<p style="margin-right:-5.65pt; text-align:justify; margin:0cm 0cm 8pt"><span style="font-size:11pt"><span style="line-height:normal"><span style="font-family:Calibri,sans-serif"><b><u>Cancelation Policy :&nbsp; &nbsp;&nbsp;</u></b>All Amendments after the receipt of Voucher will attract cancelations/retention charges as per below:</span></span></span></p>\r\n\r\n<table class="Table" style="margin-left:24.35pt; border-collapse:collapse; border:solid windowtext 1.0pt">\r\n	<tbody>\r\n		<tr>\r\n			<td style="border:solid windowtext 1.0pt; width:209.05pt; padding:0cm 5.4pt 0cm 5.4pt" valign="top" width="279">\r\n			<p style="margin-right:-5.65pt; text-align:justify; margin:0cm 0cm 8pt"><span style="font-size:11pt"><span style="line-height:normal"><span style="font-family:Calibri,sans-serif">FOR FIT BUSINESS </span></span></span></p>\r\n			</td>\r\n			<td style="border:solid windowtext 1.0pt; width:205.55pt; border-left:none; padding:0cm 5.4pt 0cm 5.4pt" valign="top" width="274">\r\n			<p style="margin-right:-5.65pt; text-align:justify; margin:0cm 0cm 8pt"><span style="font-size:11pt"><span style="line-height:normal"><span style="font-family:Calibri,sans-serif">FOR GIT /SERIES BUSINESS </span></span></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style="border:solid windowtext 1.0pt; width:209.05pt; border-top:none; padding:0cm 5.4pt 0cm 5.4pt" valign="top" width="279">\r\n			<p style="margin-right:-5.65pt; text-align:justify; margin:0cm 0cm 8pt"><span style="font-size:11pt"><span style="line-height:normal"><span style="font-family:Calibri,sans-serif">between 45- 30 days -- NIL </span></span></span></p>\r\n			</td>\r\n			<td style="border-bottom:solid windowtext 1.0pt; width:205.55pt; border-top:none; border-left:none; border-right:solid windowtext 1.0pt; padding:0cm 5.4pt 0cm 5.4pt" valign="top" width="274">\r\n			<p style="margin-right:-5.65pt; text-align:justify; margin:0cm 0cm 8pt"><span style="font-size:11pt"><span style="line-height:normal"><span style="font-family:Calibri,sans-serif">between 45- 30 days -- NIL</span></span></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style="border:solid windowtext 1.0pt; width:209.05pt; border-top:none; padding:0cm 5.4pt 0cm 5.4pt" valign="top" width="279">\r\n			<p style="margin-right:-5.65pt; text-align:justify; margin:0cm 0cm 8pt"><span style="font-size:11pt"><span style="line-height:normal"><span style="font-family:Calibri,sans-serif">Between 30- 03 days - 01-night Cancelation.</span></span></span></p>\r\n			</td>\r\n			<td style="border-bottom:solid windowtext 1.0pt; width:205.55pt; border-top:none; border-left:none; border-right:solid windowtext 1.0pt; padding:0cm 5.4pt 0cm 5.4pt" valign="top" width="274">\r\n			<p style="margin-right:-5.65pt; text-align:justify; margin:0cm 0cm 8pt"><span style="font-size:11pt"><span style="line-height:normal"><span style="font-family:Calibri,sans-serif">Between 30- 15 days &ndash; 50% Cancelation.</span></span></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style="border:solid windowtext 1.0pt; width:209.05pt; border-top:none; padding:0cm 5.4pt 0cm 5.4pt" valign="top" width="279">\r\n			<p style="margin-right:-5.65pt; text-align:justify; margin:0cm 0cm 8pt"><span style="font-size:11pt"><span style="line-height:normal"><span style="font-family:Calibri,sans-serif">Between 03-01 day/ No Show &ndash; 100 % Cancelation.</span></span></span></p>\r\n			</td>\r\n			<td style="border-bottom:solid windowtext 1.0pt; width:205.55pt; border-top:none; border-left:none; border-right:solid windowtext 1.0pt; padding:0cm 5.4pt 0cm 5.4pt" valign="top" width="274">\r\n			<p style="margin-right:-5.65pt; text-align:justify; margin:0cm 0cm 8pt"><span style="font-size:11pt"><span style="line-height:normal"><span style="font-family:Calibri,sans-serif">Between 15 -01 Day&nbsp; -- 100 % Cancelation.</span></span></span></p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n\r\n<p style="margin-right:-5.65pt; text-align:justify; margin:0cm 0cm 8pt"><span style="font-size:11pt"><span style="line-height:normal"><span style="font-family:Calibri,sans-serif"><b><u>Pre-Payment Policy</u></b></span></span></span></p>\r\n\r\n<ul>\r\n	<li style="margin-right:-5.65pt; text-align:justify; margin:0cm 0cm 8pt"><span style="font-size:11pt"><span style="line-height:normal"><span style="tab-stops:list 36.0pt"><span style="font-family:Calibri,sans-serif">Pre-payment service vouchers must be received at the time of booking for the confirmation. &nbsp;(No later than 30 days prior to the arrival date).</span></span></span></span></li>\r\n	<li style="margin-right:-5.65pt; text-align:justify; margin:0cm 0cm 8pt"><span style="font-size:11pt"><span style="line-height:normal"><span style="tab-stops:list 36.0pt"><span style="font-family:Calibri,sans-serif">All payments must be settled prior to departure from the hotel in cash/NEFT or demand draft favoring the hotel&nbsp;&nbsp;&nbsp; However, should a credit arrangement exist between our companies, the bills must be cleared within 15 days of receipt of bills. If payment is not cleared&nbsp;within 30 days than interest @ 18% will be charged.</span></span></span></span></li>\r\n</ul>\r\n\r\n<ul>\r\n</ul>\r\n\r\n<ul>\r\n</ul>\r\n', '', 'reservations@consortiumhotels.in', '', 'consoritum.php', 'sendReminderMailConsoritum.php', 'http://www.theconsortiumhotels.com', 1, 0, 0, '2018-02-03 12:34:45', '2019-01-08 17:17:12', 143),
(5, 1, 'Whtest', 'whtest@gmail.com', '', 0, '', '', 'company-logo5606.jpg', '', 'delhi', 346, 105, '110022', 'As per the government of India norms, you are requested to carry a valid photo id with complete address and produce it at the time of check in. For Indian nationals: driver''s license, passport, voter id or Aadhar card only. Pan card will not be considered as a valid address proof & for international travelers: passport.', '<ul>\r\n	<li>Full retention will be charged for cancellation received 10 days prior to arrival.</li>\r\n	<li>In the unlikely event of our inability to provide the above accommodation, we will arrange alternate accommodation of similar standards and provide transport to the guest at our cost.</li>\r\n	<li>No cancellation charges if cancelled more than 15 days prior to arrival.</li>\r\n	<li>One day pro-rata cancellation charges will be forfeited/levied for cancellation received 11-14 days prior to arrival.</li>\r\n	<li>The above cancellation policy is not valid during long weekends, Christmas, New Year and during certain other times of the year wherein rooms will be confirmed subject to non refundable advance.</li>\r\n</ul>\r\n', '<p>Enjoy the perks of being a holder of WelcomHeritage Privilege Card.</p>\r\n\r\n<p><img alt="" src="http://crs.roomstatushub.com/uploaded_files/uploads/4fa7ee8.jpg" /><br />\r\n<strong>DISCOVER PRIVILEGE CARD BENEFITS</strong></p>\r\n\r\n<ul>\r\n	<li>20% discount on the Heritage Holiday Packages.</li>\r\n	<li>20% discount on food and soft beverages.</li>\r\n	<li>Exclusive monthly Promotional offers.</li>\r\n</ul>\r\n\r\n<p>Thanking you for patronising WelcomHeritage properties and assuring you of our best services and attention at all&nbsp;times.</p>\r\n', 'test', '', '', '', '', 1, 0, 0, '2018-02-03 12:35:25', '2018-02-03 12:39:02', 9),
(6, 1, 'CONCEPT HOSPITALITY PVT LTD - THE FERN HOTELS :', 'samdel@fernhotels.com', '', 0, 'FERN', '01244017569', 'fern.png', '', 'gurgaon', 320, 105, '123123', '', '', '', '', '', '', '', '', 1, 0, 0, '2018-02-03 12:45:23', '2018-11-16 12:48:39', 16),
(7, 1, 'SOLANG VALLEY RESORTS', 'info@solangvalleyresorts.com', '', 0, 'SVR', '40525441', 'logo71144.png', 'Solang Valley, VPO Palchan', 'Manali', 321, 105, '175103', '', '<p>&nbsp;<strong>IN CASE OF NO SHOW OR LAST MINUTE CANCELLATION, RETENTION WILL BE CHARGED</strong></p>\r\n\r\n<p><span style="font-size:11pt"><span style="font-weight:700"><span style="font-family:Cambria,serif"><span style="color:black"><span style="font-style:normal"><span style="text-decoration:none">AS PER THE GOVERNMENT OF INDIA NORMS, YOU ARE REQUESTED TO CARRY A VALID PHOTO ID AND PRODUCE IT AT THE TIME OF CHECK IN. FOR INDIAN NATIONALS: DRIVERS LICENSE, PASSPORT, VOTER ID OR PAN CARD. FOR INTERNATIONAL: PASSPORT.</span></span></span></span></span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n', '', '', '', '', '', '', 1, 0, 0, '2018-05-10 12:43:58', '2018-12-01 13:57:21', 111),
(8, 1, 'HHBR', 'reservation@hhbr.in', '', 0, 'HHBR', '9531900133', '', 'NO.2, GOVIND NAGAR,HAVELOCK', 'ANDAMAN', 342, 105, '744101', '', '', '', '', '', '', '', 'hhbr.in', 1, 0, 0, '2018-06-30 17:28:03', '2018-06-30 17:28:03', 9),
(9, 1, 'Novelle Hotels', 'reservation@nouvellehotels.in', 'support@roomstatushub.com', 1, 'NH', '', 'NOUVELLE LOGO6562690183.jpg', 'E - 75, 3rd Floor, Main Road, Old Jasola Village, Jasola', 'New delhi', 346, 105, '110020', '', '<p>&bull;&nbsp;&nbsp; &nbsp;Cancellations made after the cut off period will attract retention charge equivalent to one nights room rent.<br />\r\n&bull;&nbsp;&nbsp; &nbsp;For FIT Cut Off will be 30 days from the date of arrivalbetween 1st October and 31st March and 7 daysbetween 1st April and 30th September<br />\r\n&bull;&nbsp;&nbsp; &nbsp;Groups-Cut off will be 45 days from the date of arrival between 01 October &amp; 31st March and 30 days between 01st April &amp; 30th September.<br />\r\n&bull;&nbsp;&nbsp; &nbsp;In case Voucher /Advance is not received within the stipulated period, accommodation held will be released and thereafter will be on subject to availability basis.<br />\r\nFor Groups :: The Tour operator shall submit the operations Status 45 days prior to the arrival .Final Rooming list along with vouchers to reach us 30 days prior to arrival .Should the Tour operator fail to supply such information as specified, the hotel reserve the right to release the reserved accommodations.<br />\r\nYour booking is Guaranteed against your Voucher . Any amendment henceforth will not be acceptable ( after 30 days prior to check in ) and will be subjected to Cancelation policy as per the Contract letter.<br />\r\nAssuring you of the best services at all time . you are required to send the vouchers within stipulated time , enabling us to GUARANTEE your booking.<br />\r\n&nbsp;</p>\r\n', '', '', '', '', '', '', 1, 0, 0, '2018-07-05 15:41:24', '2018-07-24 12:07:59', 118);
